from pathlib import Path
import sys
import json
from html import escape

ROOT = Path(sys.argv[1]) if len(sys.argv) > 1 else Path(__file__).resolve().parent.parent
ROOT.mkdir(parents=True, exist_ok=True)
ORIGIN = 'https://aimdownloader.pages.dev'
REPO = 'https://github.com/malikali4129/AIM-DOWNLOADER-RELEASE'
EMAIL = 'business.aliimranmalik@gmail.com'
# Change this single value and regenerate the committed HTML to update availability copy.
AVAILABILITY = 'Free to download for now'

def write(name, text):
    path = ROOT / name
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding='utf-8')

def icon(name='arrow'):
    paths = {'arrow':'M7 17 17 7M7 7h10v10', 'download':'M12 3v12m-5-5 5 5 5-5M5 16v5h14v-5', 'play':'m9 5 11 7-11 7Z', 'queue':'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01', 'audio':'M4 10v4m4-8v12m4-15v18m4-15v12m4-8v4', 'check':'m5 12 4 4L19 6', 'windows':'M3 4l8-1v8H3Zm10-1 8-1v9h-8ZM3 13h8v8l-8-1Zm10 0h8v9l-8-1Z'}
    return f'<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="{paths[name]}"/></svg>'

def brand():
    return '<a class="brand" href="/" aria-label="AIM Downloader home"><img src="/assets/brand-icon.png" width="44" height="44" alt=""><span>AIM<span class="brand-small">DOWNLOADER</span></span></a>'

def button(text, href='/download/', primary=True, extra=''):
    return f'<a class="button {"primary" if primary else "secondary"}" href="{href}" {extra}>{icon("download" if primary else "arrow")}<span>{text}</span></a>'

def github_fallback():
    return f'<a class="text-link" href="{REPO}/releases/latest">View downloads on GitHub {icon()}</a>'

def heading(kicker, title, desc):
    return f'<header class="page-heading"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{desc}</p></header>'

