support = heading('FAQ & SUPPORT', 'A little help.<br><span class="pink">A clear next step.</span>', 'Answers to the common questions, and a direct line when you need a hand.') + '<section class="wrap support-layout"><div class="faq-list">' + ''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><p>{a}</p></details>' for q,a in faqs) + f'''</div><aside class="support-card"><span class="eyebrow">STILL NEED A HAND?</span><h2>Let’s sort it out.</h2><p>For bugs, include your AIM version, Windows version, and the error you see. Leave out passwords and private links.</p><a class="button secondary" href="{REPO}/issues">{icon()}Report an issue</a><div class="support-email"><span>Email support</span><a href="mailto:{EMAIL}">{EMAIL}</a></div><p class="micro">GitHub issues are public. Email is also available for support.</p></aside></section>'''

