pages = [('/', 'Your media. Your way.', 'Download public videos, playlists, and audio with AIM Downloader for Windows. Choose the installer or portable edition.', home),('/download/','Download for Windows','Get the AIM Downloader Windows installer or portable ZIP, with the latest release details and checksums.',download),('/getting-started/','Getting started','Install AIM Downloader, complete tool setup, choose formats, and manage your first media downloads.',guide),('/support/','FAQ & support','Find answers about AIM Downloader and contact support by email or public GitHub issues.',support),('/releases/','Releases','Explore stable AIM Downloader releases and their official GitHub download assets and release notes.',releases)]

# Legal content remains part of the static build; no Python runs in the browser.
legal_docs = json.loads((Path(__file__).resolve().parent / 'legal-content.json').read_text(encoding='utf-8'))
for doc in legal_docs:
    body = '<nav class="legal-nav" aria-label="Legal documents">' + ''.join(f'<a href="{d["route"]}">{escape(d["title"])}</a>' for d in legal_docs) + '</nav>'
    body += '<p class="legal-date">Last updated: 12 September 2026</p>'
    for number, (title, paragraphs) in enumerate(doc['sections'], 1):
        body += f'<section><h2>{number}. {escape(title)}</h2>' + ''.join(f'<p>{escape(p)}</p>' for p in paragraphs) + '</section>'
    if doc.get('license_file'):
        license_text = (Path(__file__).resolve().parent.parent / doc['license_file']).read_text(encoding='utf-8')
        body += '<p>Terms supplied with a particular release govern that release. This page does not retroactively replace earlier license grants.</p><pre class="license-text">' + escape(license_text) + '</pre>'
    if doc['route'] == '/privacy/':
        body += '<section><h2>Provider privacy policies</h2><ul><li><a href="https://www.cloudflare.com/privacypolicy/">Cloudflare</a></li><li><a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub</a></li><li><a href="https://privacy.microsoft.com/privacystatement">Microsoft</a></li></ul></section>'
    body += '<p>Contact: <a href="mailto:' + EMAIL + '">' + EMAIL + '</a></p>'
    content = heading('PRIVACY & LEGAL', escape(doc['title']), escape(doc['description'])) + '<article class="wrap legal-content">' + body + '</article>'
    pages.append((doc['route'], doc['title'], doc['description'], content))

for route,title,desc,content in pages:
    write(('index.html' if route=='/' else route.strip('/')+'/index.html'), page(route,title,desc,content))
write('404.html', page('/404.html','Page not found','This page could not be found. Return to AIM Downloader.',heading('404 / WRONG TURN','This link took<br>a <span class="pink">detour.</span>','The page may have moved, but your next download is still within reach.')+f'<div class="wrap actions error-actions">{button("Back to home","/",False)}{button("Get AIM Downloader")}</div>'))
